package com.kaymlyn.planeteater.simulation.physics;

import lombok.Getter;

import java.util.Random;

/**
 * Represents a 3D vector with x, y, z components.
 * Immutable class for position, velocity, and force calculations.
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
public class Vector3D {

    private static final Random random = new Random(0);

    private final double x;
    private final double y;
    private final double z;
    
    public Vector3D(double x, double y, double z) {
        this.x = x;
        this.y = y;
        this.z = z;
    }
    
    public Vector3D(double x, double y) {
        this(x, y, 0.0);
    }

    public static Vector3D randomUnitVector() {
        double x = random.nextDouble();
        double y = random.nextDouble();
        double z = random.nextDouble();
        double magnitude = Math.sqrt(Math.pow(x,2) + Math.pow(y,2) + Math.pow(z,2));
        return new Vector3D(x/magnitude, y/magnitude, z/magnitude);
    }

    /**
     * Add another vector to this vector
     */
    public Vector3D add(Vector3D other) {
        return new Vector3D(x + other.x, y + other.y, z + other.z);
    }
    
    /**
     * Subtract another vector from this vector
     */
    public Vector3D subtract(Vector3D other) {
        return new Vector3D(x - other.x, y - other.y, z - other.z);
    }
    
    /**
     * Multiply this vector by a scalar
     */
    public Vector3D multiply(double scalar) {
        return new Vector3D(x * scalar, y * scalar, z * scalar);
    }
    
    /**
     * Divide this vector by a scalar
     */
    public Vector3D divide(double scalar) {
        if (Math.abs(scalar) < 1e-10) {
            throw new ArithmeticException("Division by zero");
        }
        return new Vector3D(x / scalar, y / scalar, z / scalar);
    }
    
    /**
     * Calculate the magnitude (length) of this vector
     */
    public double magnitude() {
        return Math.sqrt(x * x + y * y + z * z);
    }
    
    /**
     * Calculate the squared magnitude (avoids sqrt for performance)
     */
    public double magnitudeSquared() {
        return x * x + y * y + z * z;
    }
    
    /**
     * Return a normalized (unit) vector in the same direction
     */
    public Vector3D normalize() {
        double mag = magnitude();
        if (mag < 1e-10) {
            return ZERO;
        }
        return divide(mag);
    }
    
    /**
     * Calculate dot product with another vector
     */
    public double dot(Vector3D other) {
        return x * other.x + y * other.y + z * other.z;
    }
    
    /**
     * Calculate cross product with another vector
     */
    public Vector3D cross(Vector3D other) {
        return new Vector3D(
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        );
    }
    
    /**
     * Calculate distance to another point
     */
    public double distanceTo(Vector3D other) {
        return subtract(other).magnitude();
    }
    
    /**
     * Calculate squared distance (avoids sqrt for performance)
     */
    public double distanceSquaredTo(Vector3D other) {
        return subtract(other).magnitudeSquared();
    }

    public Vector3D average(Vector3D target) {
        return this.subtract(target).multiply(.5).add(target);
    }

    public double angleBetween(Vector3D that) {
        return Math.acos(this.dot(that)/(this.magnitude() * that.magnitude()));
    }

    public Vector3D rotateAroundVector(Vector3D axis, double rotationAngle) {


        Vector3D reduce = this.multiply(Math.cos(rotationAngle));
        Vector3D orientation = axis.normalize().cross(this).multiply(Math.sin(rotationAngle));
        Vector3D magnitude = axis.normalize().multiply(axis.dot(this) * (1 - Math.cos(rotationAngle)));

        return reduce.add(orientation).add(magnitude);
    }
    
    public Vector3D rotateInto3spaceFrom2space(double omega, double i, double w) {

        // Rotation matrices to transform to 3D space
        double cosO = Math.cos(omega);
        double sinO = Math.sin(omega);
        double cosi = Math.cos(i);
        double sini = Math.sin(i);
        double cosw = Math.cos(w);
        double sinw = Math.sin(w);

        // Transform from orbital plane to 3D
        double x =  this.x * (cosO * cosw - sinO * sinw * cosi) -
                    this.y * (cosO * sinw + sinO * cosw * cosi);
        double y =  this.x * (sinO * cosw + cosO * sinw * cosi) -
                    this.y * (sinO * sinw - cosO * cosw * cosi);
        double z =  this.x * (sinw * sini) +
                    this.y * (cosw * sini);

        return new Vector3D(x, y, z);
    }

    public Vector3D rotateInto3spaceFrom2space(Vector3D rotation) {
        return rotateInto3spaceFrom2space(rotation.x,rotation.y,rotation.z);
    }

    public Vector3D rotateInto2spaceFrom3space(double ascendingNode, double inclination, double periapsis) {

        double x = this.x;
        double y = this.y;
        double z = this.z;

        double cosO = Math.cos(ascendingNode);
        double sinO = Math.sin(ascendingNode);
        double cosi = Math.cos(inclination);
        double sini = Math.sin(inclination);
        double cosw = Math.cos(periapsis);
        double sinw = Math.sin(periapsis);

        // Inverse rotation (transpose of rotation matrix)
        double x_orbital = x * (cosO * cosw - sinO * sinw * cosi) +
                y * (sinO * cosw + cosO * sinw * cosi) +
                z * (sinw * sini);
        double y_orbital = -x * (cosO * sinw + sinO * cosw * cosi) -
                y * (sinO * sinw - cosO * cosw * cosi) +
                z * (cosw * sini);
        return new Vector3D(x_orbital,y_orbital);
    }

    public Vector3D rotateInto2spaceFrom3space(Vector3D rotation) {
        return rotateInto2spaceFrom3space(rotation.x,rotation.y,rotation.z);
    }
    
    @Override
    public String toString() {
        return String.format("(%.3f, %.3f, %.3f)", x, y, z);
    }
    
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Vector3D other)) return false;
        return Double.compare(x, other.x) == 0 &&
               Double.compare(y, other.y) == 0 &&
               Double.compare(z, other.z) == 0;
    }
    
    @Override
    public int hashCode() {
        int result = 17;
        long xBits = Double.doubleToLongBits(x);
        long yBits = Double.doubleToLongBits(y);
        long zBits = Double.doubleToLongBits(z);
        result = 31 * result + Long.hashCode(xBits);
        result = 31 * result + Long.hashCode(yBits);
        result = 31 * result + Long.hashCode(zBits);
        return result;
    }
    
    public static final Vector3D ZERO = new Vector3D(0, 0, 0);
    public static final Vector3D UNIT_X = new Vector3D(1, 0, 0);
    public static final Vector3D UNIT_Y = new Vector3D(0, 1, 0);
    public static final Vector3D UNIT_Z = new Vector3D(0, 0, 1);
}